import {courseLesson,edit} from './utility-authoring.js';
const L=(...args)=>courseLesson("wiz",...args);
export const wizUtilsLessons=[
L("identity","Recognize wizard identities",[32, 9],"<p>A wizard\u2019s public identity can be an ordinary player, so <code>is_wizard()</code> is broader than the raw wizard flag. <code>isnewt()</code> checks a login restriction list and requires wizard permissions; the learner receives E_PERM rather than privileged account data.</p>","target = $list_utils;\nplayer:tell(\"RAW wizard flag: \", toliteral(target.wizard));\nplayer:tell(\"WIZARD identity: \", toliteral($wiz_utils:is_wizard(target)));\nplayer:tell(\"NEWT permission guard: \", toliteral($wiz_utils:isnewt(target)));",edit("target = $list_utils;","target = $set_utils;","Inspect another utility object. It is still not a wizard identity and the restricted query remains denied.")),
L("advertised","Distinguish advertised and connected wizards",[12, 13],"<p>Advertised listings honor each wizard\u2019s advertised flag; unadvertised aliases include hidden identities. Connected listings additionally check live connections. <code>all_wizards()</code> is an alias of the advertised form in this core, not an unrestricted directory.</p>","player:tell(\"ADVERTISED: \", toliteral($wiz_utils:all_wizards_advertised()));\nplayer:tell(\"ALL alias: \", toliteral($wiz_utils:all_wizards()));\nplayer:tell(\"INCLUDING unadvertised: \", toliteral($wiz_utils:all_wizards_unadvertised()));\nplayer:tell(\"CONNECTED advertised: \", toliteral($wiz_utils:connected_wizards()));\nplayer:tell(\"CONNECTED including unadvertised: \", toliteral($wiz_utils:connected_wizards_unadvertised()));",edit("all_wizards_advertised()","all_wizards()","Replace the explicitly advertised name with its alias. The listing stays the same.")),
L("permission","Observe administrative permission guards",[0, 1, 4, 31],"<p>Changing player/programmer status can affect inheritance, registry entries, quotas and mail logs. It is not just flipping a flag. These calls run as the ordinary learner and demonstrate the E_PERM guards without modifying any account. The native follow-on exercise is to repeat on a disposable test player as a wizard and inspect each registry change.</p>","target = player;\nplayer:tell(\"SET PROGRAMMER guard: \", toliteral($wiz_utils:set_programmer(target)));\nplayer:tell(\"SET PLAYER guard: \", toliteral($wiz_utils:set_player(target)));\nplayer:tell(\"UNSET PROGRAMMER guard: \", toliteral($wiz_utils:unset_programmer(target, \"practice\")));\nplayer:tell(\"UNSET PLAYER guard: \", toliteral($wiz_utils:unset_player(target)));",edit("target = player;","target = $list_utils;","Change the target. The permission checks still reject the ordinary learner before making account changes.")),
L("ownership","Transfer ownership and property ownership",[2, 3, 28],"<p>Object ownership, c-property ownership and verb ownership are distinct. <code>set_owner()</code> updates the object and c properties; <code>set_property_owner()</code> may propagate through descendants; <code>grant_object()</code> also handles eligible verbs and non-c properties. Use a disposable fixture and compare owners before and after.</p>","o = create(#-1);\nadd_property(o, \"sample\", 3, {player, \"rc\"});\nplayer:tell(\"OWNER before: \", toliteral(o.owner));\nplayer:tell(\"SET OWNER result: \", toliteral($wiz_utils:set_owner(o, player)));\nplayer:tell(\"PROPERTY OWNER result: \", toliteral($wiz_utils:set_property_owner(o, \"sample\", player)));\nplayer:tell(\"GRANT result: \", toliteral($wiz_utils:grant_object(o, player)));\nplayer:tell(\"OWNER after: \", toliteral(o.owner));\nrecycle(o);",edit("\"sample\", 3","\"sample\", 5","Change the property value. Ownership operations preserve its data; inspect sample to confirm it remains five."),{"server": {"names": ["set_owner", "set_property_owner", "grant_object"], "prerequisites": "An isolated ToastStunt server; execute as a wizard test player with no live accounts or outbound mail. Use only the scratch object created by this code.", "manual": true, "expectedEffect": "With player a wizard test account and already the owner, ownership remains that account. The grant still yields; it reports nothing changed when all eligible members already match."}}),
L("property-flags","Propagate property flags through descendants",[5],"<p>Unlike plain <code>set_property_info()</code>, this helper updates descendant instances and adjusts ownership for the c flag. Call the public wrapper; its internal recursive worker rejects external callers.</p>","o = create(#-1);\nchild = create(o);\nadd_property(o, \"sample\", 3, {player, \"rc\"});\nplayer:tell(\"FLAGS before: \", toliteral(property_info(child, \"sample\")[2]));\nplayer:tell(\"SET flags: \", toliteral($wiz_utils:set_property_flags(o, \"sample\", \"r\")));\nplayer:tell(\"FLAGS after: \", toliteral(property_info(child, \"sample\")[2]));\nrecycle(child);\nrecycle(o);",edit("\"sample\", \"r\"","\"sample\", \"rw\"","Enable writing as well. Descendant flags become rw instead of r.")),
L("email","Read and replace an email field",[40, 41],"<p>The field may be a string or a list whose first item is the address. These wrappers preserve the other list fields. They change stored data only; they do not send mail. Use a scratch object with a made-up example.invalid address.</p>","o = create(#-1);\nadd_property(o, \"email_address\", {\"old@example.invalid\", \"note\"}, {player, \"rc\"});\nplayer:tell(\"EMAIL before: \", toliteral($wiz_utils:get_email_address(o)));\n$wiz_utils:set_email_address(o, \"new@example.invalid\");\nplayer:tell(\"EMAIL after: \", toliteral($wiz_utils:get_email_address(o)));\nplayer:tell(\"FULL field: \", toliteral(o.email_address));\nrecycle(o);",edit("new@example.invalid","other@example.invalid","Use another test address. The note in the second list position remains unchanged.")),
L("passwords","Inspect the historical password helper",[7, 29],"<p>The pronounceable-password helper alternates vowels and consonants; it is a historical core convenience, not a modern password policy. Connection hashing combines an object and host string before crypt. Never use real credentials or host records in examples.</p>","length = 8;\npassword = $wiz_utils:random_password(length);\nplayer:tell(\"GENERATED length: \", toliteral(length(password)));\nplayer:tell(\"ZERO length result: \", toliteral($wiz_utils:random_password(0)));\nplayer:tell(\"CONNECTION hash: \", toliteral($wiz_utils:connection_hash(player, \"example.invalid\", \"ab\")));",edit("length = 8;","length = 10;","Request ten characters. The length changes to ten; the zero-length error and fixed-input hash stay unchanged."),{"server": {"names": ["random_password", "connection_hash"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("queues","Inspect queues and permission rotation",[8, 39],"<p>Queued-task access is constrained by the caller\u2019s ability to adopt the requested permissions. Despite its name, <code>random_wizard()</code> cycles through the configured wizard list; it mutates the rotation index and can fail if the list is empty.</p>","player:tell(\"OWN queue: \", toliteral($wiz_utils:queued_tasks(player)));\nplayer:tell(\"NEXT permission owner: \", toliteral($wiz_utils:random_wizard()));\nplayer:tell(\"NEXT permission owner again: \", toliteral($wiz_utils:random_wizard()));",edit("queued_tasks(player)","queued_tasks(caller_perms())","Request the current permission identity explicitly. In this direct invocation it is the same test account."),{"server": {"names": ["queued_tasks", "random_wizard"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("registry","Check a registration request before creating an account",[20, 21, 23],"<p>Validation can return an explanation string; an empty string means the request passed. <code>make_player()</code> assumes validation already happened, initializes several services and returns a player/password pair. <code>do_make_player()</code> is the interactive command workflow with extra prompts and logs.</p>","name = \"UtilityPractice\";\naddress = \"practice@example.invalid\";\nreason = $wiz_utils:check_player_request(name, address);\nplayer:tell(\"REQUEST validation: \", toliteral(reason));\nif (!reason)\n  created = $wiz_utils:make_player(name, address, \"disposable lesson\");\n  player:tell(\"CREATED object: \", created[1]);\nendif",edit("UtilityPractice","UtilityPracticeTwo","Use a second unique test name. Name availability changes with existing registry entries; discard the test database after the exercise."),{"server": {"names": ["check_player_request", "make_player", "do_make_player"], "prerequisites": "A disposable full ToastCore server, wizard test account, working quota/player/registration services and outbound networking disabled. Use no real email address.", "manual": true, "expectedEffect": "Validation either prints the precise rejection or creates a new test player. The helper\u2019s second return item is a generated password; do not publish it. For the interactive alternative call do_make_player with the same arguments on a fresh disposable database."}}),
L("registration-changes","Update registration and handle password delivery",[22, 24, 25],"<p>These are interactive account workflows, not simple field setters. Registration updates the registration database; password changes update timestamps and may offer delivery. <code>send_new_player_mail()</code> delegates to the network service. Keep outbound networking disabled and use only a disposable account.</p>","test_player = player;\nplayer:tell(\"Run this only as the disposable wizard test account.\");\n$wiz_utils:do_register(test_player.name, \"changed@example.invalid\", \"lesson fixture\");\n$wiz_utils:do_new_password(test_player, \"Disposable-Lesson-Only\");",edit("changed@example.invalid","updated@example.invalid","Change the synthetic address and decline any mail prompt. Compare the stored email and registration record after the change."),{"server": {"names": ["do_register", "do_new_password", "send_new_player_mail"], "prerequisites": "A disposable wizard account on a local full-core server. Networking must be disabled; decline delivery prompts. These operations change that test account\u2019s credentials.", "manual": true, "expectedEffect": "The registration report shows the old and new address. The password workflow reports its change and any mail prompt; decline delivery. Inspect send_new_player_mail to see where the network handoff occurs."}}),
L("restrictions","Understand programmer restrictions and newting",[30, 35],"<p>Programmer restrictions may expire using recorded uptime, while newting records a login restriction, disconnects the target and logs the action. Checking programmer restrictions can itself remove expired entries. Work on a separate disposable player, never the administrator running the exercise.</p>","test_player = $player;\nplayer:tell(\"Replace test_player with a separate disposable player first.\");\nplayer:tell(\"RESTRICTION state: \", toliteral($wiz_utils:check_prog_restricted(test_player)));",edit("test_player = $player;","test_player = $guest;","Compare another class object\u2019s restriction state. For the administrative follow-on, create a disposable account, call <code>newt_player(account, \"lesson fixture\")</code>, and verify isnewt as wizard."),{"server": {"names": ["check_prog_restricted", "newt_player"], "prerequisites": "A disposable server with two test accounts, wizard permission, working login and internal mail services, outbound networking disabled.", "manual": true, "expectedEffect": "The initial read returns the restriction state. In the follow-on, newt_player adds the disposable account to the login restriction list and disconnects it. The newt log records the supplied reason."}}),
L("owned-index","Rebuild and verify owned-object indexes",[10, 11],"<p>The owned_objects property is bookkeeping, not the authoritative owner field. Initialization scans the database to add objects, then verification removes stale entries and reconciles owners. Both operations may yield; run them only on a disposable copy while learning.</p>","player:tell(\"OWNED index rebuild:\");\n$wiz_utils:initialize_owned();\nplayer:tell(\"OWNED index verification:\");\n$wiz_utils:verify_owned_objects();",edit("\"OWNED index verification:\"","\"SECOND verification pass:\"","Run the verification again after rebuilding. With no ownership changes, it should find no further stale entries."),{"server": {"names": ["initialize_owned", "verify_owned_objects"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "Initialization prints progress and completion. Verification prints corrections only where stale entries existed. Inspect owned_objects alongside actual object.owner values."}}),
L("rename-verbs","Rename local verb definitions",[14],"<p>This helper repeatedly renames matching definitions on the specified object; despite its name it does not traverse descendants. The pinned core can loop until tick exhaustion when an existing match cannot be renamed under the helper\u2019s permissions. This safe example exercises the no-match result; inspect the caught set_verb_info failure in the source before using it on definitions.</p>","o = create(#-1);\nadd_verb(o, {player, \"rxd\", \"oldname\"}, {\"this\", \"none\", \"this\"});\nplayer:tell(\"RENAME result: \", toliteral($wiz_utils:rename_all_instances(o, \"missing\", \"newname\")));\nplayer:tell(\"VERBS after: \", toliteral(verbs(o)));\nrecycle(o);",edit("\"newname\"","\"freshname\"","Choose a different nonmatching destination name. No matching verb is found, so the listing keeps oldname."),{"server": {"names": ["rename_all_instances"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object.", "wizard": true}}),
L("connection-reports","Read administrative connection reports",[18, 19],"<p>These reports expose connection history and require wizard permission. The listing form uses selected players; the from-listing form searches site records, with wildcard searches potentially scanning every player. Output rows depend on the server\u2019s test connections.</p>","player:tell(\"SELECTED player report:\");\n$wiz_utils:show_netwho_listing(player, {player});\nplayer:tell(\"SYNTHETIC site report:\");\n$wiz_utils:show_netwho_from_listing(player, \"example.invalid\");",edit("example.invalid","another.invalid","Search another synthetic site. A site with no test records produces a no-match message."),{"server": {"names": ["show_netwho_listing", "show_netwho_from_listing"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "The selected-player report shows the test account\u2019s connection information. The synthetic site search reports no matching sites unless you populated a matching test record."}}),
L("maintenance","Inspect recurring cleanup services",[27, 33, 34, 36, 37, 38],"<p>Idle booting, mail expiration and editor cleanup affect shared server state. Weekly wrappers fork recurring tasks; calling them twice can schedule duplicate work. Inspect the queue and use a disposable database with only test mail and editor sessions. The one-shot mail expiration wrapper invokes list and player passes.</p>","player:tell(\"ONE-SHOT mail expiration:\");\n$wiz_utils:expire_mail();\nplayer:tell(\"Inspect expired test messages and internal summary mail.\");",edit("$wiz_utils:expire_mail();","$wiz_utils:expire_mail_players();","Run only the player pass. Mailing-list messages are no longer processed by that invocation. Separately inspect boot_idlers, expire_mail_weekly and flush_editors for their fork intervals before scheduling them."),{"server": {"names": ["expire_mail", "expire_mail_players", "expire_mail_lists", "expire_mail_weekly", "boot_idlers", "flush_editors"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "Expired test messages are removed according to each recipient\u2019s policy, and internal summary mail is produced. The one-shot call does not install the weekly wrapper. Recurring jobs must be inspected and stopped before discarding the test server."}}),
L("help-report","Report missing help topics",[16],"<p>The missing-help report sorts recorded miss and ambiguity counts and applies a strict greater-than threshold. It prints a heading and individual rows. The internal recorder only accepts calls from the player help path, so do not simulate it with arbitrary direct calls.</p>","threshold = 5;\nplayer:tell(\"MISSING HELP report:\");\n$wiz_utils:show_missing_help(threshold);",edit("threshold = 5;","threshold = 0;","Lower the threshold to zero. Recorded topics with positive counts now qualify."),{"server": {"names": ["show_missing_help"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "The report prints its heading and qualifying rows after its native sorting task completes. With no recorded misses it prints only the heading and closing rule."}}),
L("admin-report","Assemble a read-only administrative overview",[],"<p>Combine identity and listing checks without changing accounts. Keep advertised identities separate from currently connected identities; the difference is expected when administrators are offline.</p>","player:tell(\"LEARNER wizard identity: \", toliteral($wiz_utils:is_wizard(player)));\nplayer:tell(\"ADVERTISED count: \", toliteral(length($wiz_utils:all_wizards_advertised())));\nplayer:tell(\"CONNECTED count: \", toliteral(length($wiz_utils:connected_wizards())));",edit("all_wizards_advertised()","all_wizards_unadvertised()","Include unadvertised identities in the count. The connected advertised count remains a separate measure.")),
];
export const wizExclusions={"6": "Internal recursive worker; source explicitly says not to call it directly. Covered through set_property_flags().", "15": "Internal missing-help instrumentation accepts only the player help call path. Public reporting is taught with show_missing_help().", "17": "Core initialization hook resets administration state; not an ordinary utility call.", "26": "Legacy alternative ownership implementation. Teach the maintained set_owner() and grant_object() interfaces instead."};
